16	#include <functional>
17	
18	using namespace std;
19	using namespace mup;
20	
21	Trace::Trace(QString name, QColor color, QString live)
22	    : model(nullptr),
23	      _name(name),
24	      _color(color),
25	      source(Source::Live),
26	      hash(0),
27	      hashSet(false),
28	      JSONskipHash(false),
29	      _liveType(LivedataType::Overwrite),
30	      liveParam(live),
31	      fileParameter(0),
32	      mathUpdateBegin(0),
33	      mathUpdateEnd(0),
34	      vFactor(0.66),
35	      reflection(true),
36	      visible(true),
37	      paused(false),
38	      reference_impedance(50.0),
39	      domain(DataType::Frequency),
40	      deembeddingActive(false),
41	      deembedded_reference_impedance(50.0),
42	      lastMath(nullptr)
43	{
44	    settings.valid = false;
45	    MathInfo self = {.math = this, .enabled = true};
46	    mathOps.push_back(self);
47	    updateLastMath(mathOps.rbegin());
48	
49	    lastMathUpdate = QTime::currentTime();
50	    mathCalcTimer.setSingleShot(true);
51	    connect(&mathCalcTimer, &QTimer::timeout, this, &Trace::calculateMath);
52	
53	    fromLivedata(LivedataType::Overwrite, live);
54	
55	    self.enabled = false;
56	    dataType = DataType::Frequency;
57	    connect(this, &Trace::typeChanged, [=](){
58	        dataType = domain;
59	        emit outputTypeChanged(dataType);
60	    });
61	    connect(this, &Trace::outputSamplesChanged, [=](unsigned int begin, unsigned int end){
62	        Q_UNUSED(end);
63	        // some samples changed, delete unwrapped phases from here until the end
64	        if(unwrappedPhase.size() > begin) {
65	            unwrappedPhase.resize(begin);
66	        }
67	    });
68	}
