94	void Trace::addData(const Trace::Data& d, DataType domain, double reference_impedance, int index) {
95	    if(this->domain != domain) {
96	        clear();
97	        this->domain = domain;
98	        emit typeChanged(this);
99	    }
100	    bool referenceImpedanceChanged = false;
101	    {
102	        QMutexLocker locker(&dataMutex);
103	        if(index >= 0) {
104	            // index position specified
105	            if(data.size() <= (unsigned int) index) {
106	                data.resize(index + 1);
107	            }
108	            data[index] = d;
109	        } else {
110	            // no index given, determine position by X-coordinate
111	
112	            // add or replace data in vector while keeping it sorted with increasing frequency
113	            auto lower = lower_bound(data.begin(), data.end(), d, [](const Data &lhs, const Data &rhs) -> bool {
114	                return lhs.x < rhs.x;
115	            });
116	            // calculate index now because inserting a sample into data might lead to reallocation -> arithmetic on lower not valid anymore
117	            index = lower - data.begin();
118	            if(lower == data.end()) {
119	                // highest frequency yet, add to vector
120	                data.push_back(d);
121	            } else if(lower->x == d.x) {
122	                switch(_liveType) {
123	                case LivedataType::Overwrite:
124	                    // replace this data element
125	                    *lower = d;
126	                    break;
127	                case LivedataType::MaxHold:
128	                    // replace this data element
129	                    if(abs(d.y) > abs(lower->y)) {
130	                        *lower = d;
131	                    }
132	                    break;
133	                case LivedataType::MinHold:
134	                    // replace this data element
135	                    if(abs(d.y) < abs(lower->y)) {
136	                        *lower = d;
137	                    }
138	                    break;
139	                default: break;
140	                }
141	            } else {
142	                // insert at this position
143	                data.insert(lower, d);
144	            }
145	        }
146	        if(this->reference_impedance != reference_impedance) {
147	            this->reference_impedance = reference_impedance;
148	            referenceImpedanceChanged = true;
149	        }
150	    }
151	    if(referenceImpedanceChanged) {
152	        emit typeChanged(this);
153	    }
154	    success();
155	    emit outputSamplesChanged(index, index + 1);
156	}
