170	void Trace::addDeembeddingData(const Trace::Data &d, double reference_impedance, int index)
171	{
172	    bool wasAvailable = false;
173	    bool referenceImpedanceChanged = false;
174	    {
175	        QMutexLocker locker(&dataMutex);
176	        wasAvailable = deembeddingData.size() > 0;
177	        if(index >= 0) {
178	            // index position specified
179	            if(deembeddingData.size() <= (unsigned int) index) {
180	                deembeddingData.resize(index + 1);
181	            }
182	            deembeddingData[index] = d;
183	        } else {
184	            // no index given, determine position by X-coordinate
185	
186	            // add or replace data in vector while keeping it sorted with increasing frequency
187	            auto lower = lower_bound(deembeddingData.begin(), deembeddingData.end(), d, [](const Data &lhs, const Data &rhs) -> bool {
188	                return lhs.x < rhs.x;
189	            });
190	            // calculate index now because inserting a sample into data might lead to reallocation -> arithmetic on lower not valid anymore
191	            index = lower - deembeddingData.begin();
192	            if(lower == deembeddingData.end()) {
193	                // highest frequency yet, add to vector
194	                deembeddingData.push_back(d);
195	            } else if(lower->x == d.x) {
196	                *lower = d;
197	            } else {
198	                // insert at this position
199	                deembeddingData.insert(lower, d);
200	            }
201	        }
202	        if(deembedded_reference_impedance != reference_impedance) {
203	            deembedded_reference_impedance = reference_impedance;
204	            referenceImpedanceChanged = deembeddingActive;
205	        }
206	    }
207	    if(referenceImpedanceChanged) {
208	        emit typeChanged(this);
209	    }
210	    if(deembeddingActive) {
211	        emit outputSamplesChanged(index, index + 1);
212	    }
213	    if(!wasAvailable) {
214	        emit deembeddingChanged(this);
215	    }
216	}
