228	void Trace::fillFromTouchstone(Touchstone &t, unsigned int parameter)
229	{
230	    if(parameter >= t.ports()*t.ports()) {
231	        throw runtime_error("Parameter for touchstone out of range");
232	    }
233	    clear();
234	    domain = DataType::Frequency;
235	    fileParameter = parameter;
236	    filename = t.getFilename();
237	    for(unsigned int i=0;i<t.points();i++) {
238	        auto tData = t.point(i);
239	        Data d;
240	        d.x = tData.frequency;
241	        d.y = t.point(i).S[parameter];
