244	    // check if parameter is a reflection measurement (e.i. S11/S22/S33/...)
245	    reflection = false;
246	    for (unsigned int i = 0; i * i <= parameter; i++) {
247	        if (parameter == i * t.ports() + i) {
248	            reflection = true;
249	            break;
250	        }
251	    }
252	    clearMathSources();
253	    source = Source::File;
254	    reference_impedance = t.getReferenceImpedance();
255	    emit typeChanged(this);
256	    emit outputSamplesChanged(0, data.size());
257	}
