259	QString Trace::fillFromCSV(CSV &csv, unsigned int parameter)
260	{
261	    // find correct column
262	    int traceNum = -1;
263	    unsigned int i=1;
264	    QString lastTraceName = "";
265	    std::map<YAxis::Type, int> columnMapping;
266	    for(;i<csv.columns();i++) {
267	        auto header = csv.getHeader(i);
268	        auto splitIndex = header.lastIndexOf("_");
269	        if(splitIndex == -1) {
270	            // no "_", not following naming format of CSV export, skip
271	            continue;
272	        }
273	        auto traceName = header.left(splitIndex);
274	        auto yaxistype = header.right(header.size() - splitIndex - 1);
275	        if(traceName != lastTraceName) {
276	            traceNum++;
277	            if(traceNum > (int) parameter) {
278	                // got all columns for the trace we are interested in
279	                break;
280	            }
281	            lastTraceName = traceName;
282	        }
283	        if(traceNum == (int) parameter) {
284	            // this is the trace we are looking for, get axistype and add to mapping
285	
286	            // handle legacy column naming, translate to new naming
287	            if(yaxistype == "real") {
288	                yaxistype = YAxis::TypeToName(YAxis::Type::Real);
289	            } else if(yaxistype == "imag") {
290	                yaxistype = YAxis::TypeToName(YAxis::Type::Imaginary);
291	            }
292	
293	            columnMapping[YAxis::TypeFromName(yaxistype)] = i;
294	        }
295	    }
296	    if(traceNum < (int) parameter) {
297	        throw runtime_error("Not enough traces in CSV file");
298	    }
299	    if(columnMapping.size() == 0) {
300	        throw runtime_error("No data for trace in CSV file");
301	    }
302	
303	    clear();
304	    fileParameter = parameter;
305	    filename = csv.getFilename();
306	    auto xColumn = csv.getColumn(0);
307	    if(csv.getHeader(0).compare("time", Qt::CaseInsensitive) == 0) {
308	        domain = DataType::Time;
309	    } else if(csv.getHeader(0).compare("power", Qt::CaseInsensitive) == 0) {
310	        domain = DataType::Power;
311	    } else if(csv.getHeader(0).compare("time (zero span)", Qt::CaseInsensitive) == 0) {
312	        domain = DataType::TimeZeroSpan;
313	    } else {
314	        domain = DataType::Frequency;
315	    }
316	    for(unsigned int i=0;i<xColumn.size();i++) {
317	        std::map<YAxis::Type, double> data;
318	        for(auto map : columnMapping) {
319	            data[map.first] = csv.getColumn(map.second)[i];
320	        }
321	        Data d;
322	        d.x = xColumn[i];
323	        d.y = YAxis::reconstructValueFromYAxisType(data);
324	        addData(d, domain);
325	    }
326	    reflection = false;
327	    clearMathSources();
328	    source = Source::File;
329	    emit typeChanged(this);
330	    emit outputSamplesChanged(0, data.size());
331	    return lastTraceName;
332	}
