334	void Trace::fillFromDatapoints(std::map<QString, Trace *> traceSet, const std::vector<DeviceDriver::VNAMeasurement> &data, bool deembedded)
335	{
336	    // remove all previous points
337	    for(auto m : traceSet) {
338	        if(!m.second) {
339	            // no trace, skip
340	            continue;
341	        }
342	        if(!deembedded) {
343	            m.second->clear();
344	        } else {
345	            m.second->clearDeembedding();
346	        }
347	    }
348	    // add new points to traces
349	    for(auto d : data) {
350	        Trace::Data td;
351	        td.x = d.frequency;
352	        for(auto m : d.measurements) {
353	            td.y = m.second;
354	            QString measurement = m.first;
355	            if(traceSet.count(measurement)) {
356	                if(!traceSet[measurement]) {
357	                    // no trace, skip
358	                    continue;
359	                }
360	                if(!deembedded) {
361	                    traceSet[measurement]->addData(td, DataType::Frequency);
362	                } else {
363	                    traceSet[measurement]->addDeembeddingData(td, d.Z0);
364	                }
365	            }
366	        }
367	    }
368	}
