436	QString Trace::getMathFormulaError() const
437	{
438	    if(mathFormula.isEmpty()) {
439	        return "Math formula must not be empty";
440	    }
441	    try {
442	        ParserX parser(pckCOMMON | pckUNIT | pckCOMPLEX);
443	        parser.SetExpr(mathFormula.toStdString());
444	        auto vars = parser.GetExprVar();
445	        for(auto var : vars) {
446	            auto varName = QString::fromStdString(var.first);
447	            // try to find variable name
448	            bool found = false;
449	            for(auto ms : mathSourceTraces) {
450	                if(ms.second == varName) {
451	                    found = true;
452	                    break;
453	                }
454	            }
455	            if(varName == "x") {
456	                found = true;
457	            }
458	            if(!found) {
