484	void Trace::updateMathTracePoints()
485	{
486	    if(paused) {
487	        // do not update when paused
488	        return;
489	    }
490	    if(!mathSourceTraces.size()) {
491	        return;
492	    }
493	    double startX = std::numeric_limits<double>::lowest();
494	    double stopX = std::numeric_limits<double>::max();
495	    double stepSize = std::numeric_limits<double>::max();
496	    auto domain = DataType::Invalid;
497	    for(auto t : mathSourceTraces) {
498	        if(domain == DataType::Invalid) {
499	            domain = t.first->outputType();
500	        } else {
501	            if(domain != t.first->outputType()) {
502	                // not all traces have the same domain, clear output and do not calculate
503	                {
504	                    QMutexLocker locker(&dataMutex);
505	                    data.resize(0);
506	                }
507	                mathUpdateBegin = 0;
508	                mathUpdateEnd = 0;
509	                dataType = DataType::Invalid;
510	                emit outputTypeChanged(dataType);
511	                return;
512	            }
513	        }
514	        if(t.first->minX() > startX) {
515	            startX = t.first->minX();
516	        }
517	        if(t.first->maxX() < stopX) {
518	            stopX = t.first->maxX();
519	        }
520	        double traceStepSize = std::numeric_limits<double>::max();
521	        if(t.first->numSamples() > 1) {
522	            traceStepSize = (t.first->maxX() - t.first->minX()) / (t.first->numSamples() - 1);
523	        }
524	        if(traceStepSize < stepSize) {
525	            stepSize = traceStepSize;
526	        }
527	    }
528	    if(domain != this->domain) {
529	        this->domain = domain;
530	        emit typeChanged(this);
531	    }
532	    unsigned int samples = 0;
533	    if(stopX > startX) {
534	        samples = round((stopX - startX) / stepSize + 1);
535	    }
536	//    qDebug() << "Updated trace points, now"<<samples<<"points from"<<startX<<"to"<<stopX;
537	    {
538	        QMutexLocker locker(&dataMutex);
539	        if(samples != data.size()) {
540	            auto oldSize = data.size();
541	            data.resize(samples);
542	            if(oldSize < samples) {
543	                for(unsigned int i=oldSize;i<samples;i++) {
544	                    data[i].x = startX + i * stepSize;
545	                    data[i].y = numeric_limits<complex<double>>::quiet_NaN();
546	                }
547	            }
548	        }
549	        if(samples > 0 && (startX != data.front().x || stopX != data.back().x || mathUpdateEnd > samples)) {
550	            // something changed in the data which affects X axis scaling, update all X values and schedule math calculation for all points
551	            for(unsigned int i=0;i<samples;i++) {
552	                data[i].x = startX + i * stepSize;
553	            }
554	            mathUpdateBegin = 0;
555	            mathUpdateEnd = samples;
556	        }
557	    }
558	}
