569	void Trace::scheduleMathCalculation(unsigned int begin, unsigned int end)
570	{
571	//    qDebug() << "Scheduling calculation from"<<begin<<"to"<<end;
572	    if(source != Source::Math) {
573	        return;
574	    }
575	    if(begin < mathUpdateBegin) {
576	        mathUpdateBegin = begin;
577	    }
578	    if(end > mathUpdateEnd) {
579	        mathUpdateEnd = end;
580	    }
581	    auto now = QTime::currentTime();
582	    if (lastMathUpdate.msecsTo(now) >= MinMathUpdateInterval) {
583	        calculateMath();
584	    } else {
585	        mathCalcTimer.start(MinMathUpdateInterval);
586	    }
587	}
588	
589	void Trace::calculateMath()
590	{
591	    lastMathUpdate = QTime::currentTime();
592	    const auto updateBegin = mathUpdateBegin;
593	    const auto updateEnd = mathUpdateEnd;
594	    if(updateEnd <= updateBegin) {
595	        // nothing to do
596	        return;
597	    }
598	    unsigned int dataSize = 0;
599	    vector<double> xValues;
600	    {
601	        QMutexLocker locker(&dataMutex);
602	        dataSize = data.size();
603	        if(updateBegin < dataSize && updateEnd < dataSize + 1) {
604	            xValues.reserve(updateEnd - updateBegin);
605	            for(unsigned int i=updateBegin;i<updateEnd;i++) {
606	                xValues.push_back(data[i].x);
607	            }
608	        }
609	    }
610	    if(updateBegin >= dataSize || updateEnd >= dataSize + 1) {
611	        qWarning() << "Not calculating math trace, out of limits. Requested from" << updateBegin << "to" << updateEnd <<" but data is of size" << dataSize;
612	        return;
613	    }
614	    if(mathFormula.isEmpty()) {
615	        error("Expression is empty");
616	        return;
617	    }
618	    if(!isPaused()) {
619	        vector<complex<double>> results(xValues.size(), numeric_limits<complex<double>>::quiet_NaN());
620	        try {
621	            ParserX parser(pckCOMMON | pckUNIT | pckCOMPLEX);
622	            parser.SetExpr(mathFormula.toStdString());
623	            map<Trace*,Value> values;
624	            Value x;
625	            parser.DefineVar("x", Variable(&x));
626	            for(const auto &ts : mathSourceTraces) {
627	                values[ts.first] = Value();
628	                parser.DefineVar(ts.second.toStdString(), Variable(&values[ts.first]));
629	            }
630	            for(unsigned int i=0;i<xValues.size();i++) {
631	                x = xValues[i];
632	                for(auto &val : values) {
633	                    val.second = val.first->interpolatedSample(xValues[i]).y;
634	                }
635	                Value res = parser.Eval();
636	                results[i] = res.GetComplex();
637	            }
638	        } catch (const ParserError &e) {
639	            error(QString::fromStdString(e.GetMsg()));
640	        }
641	        {
642	            QMutexLocker locker(&dataMutex);
643	            for(unsigned int i=0;i<results.size();i++) {
644	                if(updateBegin + i < data.size()) {
645	                    data[updateBegin + i].y = results[i];
646	                }
647	            }
648	        }
649	        success();
650	        emit outputSamplesChanged(updateBegin, updateEnd + 1);
651	    }
652	    {
653	        QMutexLocker locker(&dataMutex);
654	        mathUpdateBegin = data.size();
655	    }
656	    mathUpdateEnd = 0;
657	}
