701	
702	bool Trace::canAddAsMathSource(Trace *t)
703	{
704	    if(t == this) {
705	        // can't add itself
706	        return false;
707	    }
708	    // check if we would create a loop of math traces depending on each other
709	    if(t->mathDependsOn(this)) {
710	        return false;
711	    }
712	    if(mathSourceTraces.size() == 0) {
713	        // no traces used as source yet, can add anything
714	        return true;
715	    } else {
716	        // can only add traces of the same domain
717	        if(mathSourceTraces.begin()->first->outputType() == t->outputType()) {
718	            return true;
719	        } else {
720	            return false;
721	        }
722	    }
723	}
724	
725	bool Trace::addMathSource(Trace *t, QString variableName)
726	{
727	    if(mathSourceTraces.count(t)) {
728	        // this trace is already used as a math source
729	        mathSourceTraces[t] = variableName;
730	        return true;
731	    }
732	//    qDebug() << "Adding trace" << t << "as a math source to" << this << "as variable" << variableName;
733	    if(!canAddAsMathSource(t)) {
734	        return false;
735	    }
736	    mathSourceTraces[t] = variableName;
737	    connect(t, &Trace::deleted, this, &Trace::mathSourceTraceDeleted, Qt::UniqueConnection);
738	    connect(t, &Trace::dataChanged, this, [=](unsigned int begin, unsigned int end){
739	        updateMathTracePoints();
740	        auto startX = t->sample(begin).x;
741	        auto stopX = t->sample(end-1).x;
742	
743	//        qDebug() << "Source update from"<<startX<<"to"<<stopX<<". Index from"<<begin<<"to"<<end;
744	
745	        auto calcIndex = [&](double x) -> int {
746	            if(data.size() == 0) {
747	                return 0;
748	            }
749	            auto lower = lower_bound(data.begin(), data.end(), x, [](const Data &lhs, const double x) -> bool {
750	                return lhs.x < x;
751	            });
752	            if(lower == data.end()) {
753	                // actually beyond the last sample, return the index of the last anyway to avoid access past data
754	                return data.size() - 1;
755	            }
756	            return lower - data.begin();
757	        };
758	
759	        scheduleMathCalculation(calcIndex(startX), calcIndex(stopX)+1);
760	    });
761	    updateMathTracePoints();
762	    scheduleMathCalculation(0, data.size());
763	    return true;
764	}
