850	nlohmann::json Trace::toJSON()
851	{
852	    nlohmann::json j;
853	    if(!JSONskipHash) {
854	        j["hash"] = toHash(true);
855	    }
856	    j["name"] = _name.toStdString();
857	    j["color"] = _color.name().toStdString();
858	    j["visible"] = visible;
859	    switch(source) {
860	    case Source::Live:
861	        j["type"] = "Live";
862	        j["parameter"] = liveParam.toStdString();
863	        j["livetype"] = _liveType;
864	        j["paused"] = paused;
865	        break;
866	    case Source::File:
867	        j["type"] = "File";
868	        j["filename"] = filename.toStdString();
869	        j["parameter"] = fileParameter;
870	        break;
871	    case Source::Math: {
872	        j["type"] = "Math";
873	        j["expression"] = mathFormula.toStdString();
874	        nlohmann::json jsources;
875	        for(auto ms : mathSourceTraces) {
876	            nlohmann::json jsource;
877	            jsource["trace"] = ms.first->toHash();
878	            jsource["variable"] = ms.second.toStdString();
879	            jsources.push_back(jsource);
880	        }
881	        j["sources"] = jsources;
882	    }
883	        break;
884	    case Source::Calibration:
885	        j["type"] = "Calibration";
886	        break;
887	    case Source::Last:
888	        break;
889	    }
890	    j["velocityFactor"] = vFactor;
891	    j["referenceImpedance"] = reference_impedance;
892	    j["reflection"] = reflection;
893	
894	    auto &pref = Preferences::getInstance();
895	    vector<Data> traceData;
896	    vector<Data> deembeddingDataCopy;
897	    {
898	        QMutexLocker locker(&dataMutex);
899	        if(pref.Debug.saveTraceData) {
900	            traceData = data;
901	        }
902	        deembeddingDataCopy = deembeddingData;
903	    }
904	    if(pref.Debug.saveTraceData) {
905	        nlohmann::json jdata;
906	        for(const auto &d : traceData) {
907	            nlohmann::json jpoint;
908	            jpoint["x"] = d.x;
909	            jpoint["real"] = d.y.real();
910	            jpoint["imag"] = d.y.imag();
911	            jdata.push_back(jpoint);
912	        }
913	        j["data"] = jdata;
914	    }
915	
916	    j["deembeddingActive"] = deembeddingActive;
917	    nlohmann::json jdedata;
918	    for(const auto &d : deembeddingDataCopy) {
919	        nlohmann::json jpoint;
920	        jpoint["x"] = d.x;
921	        jpoint["real"] = d.y.real();
922	        jpoint["imag"] = d.y.imag();
923	        jdedata.push_back(jpoint);
924	    }
925	    j["deembeddingData"] = jdedata;
926	
927	    nlohmann::json mathList;
928	    for(auto m : mathOps) {
929	        if(m.math->getType() == Type::Last) {
930	            // this is an invalid type reserved for the trace itself, skip
931	            continue;
932	        }
933	        nlohmann::json jm;
934	        auto info = TraceMath::getInfo(m.math->getType());
935	        jm["operation"] = info.name.toStdString();
936	        jm["enabled"] = m.enabled;
937	        jm["settings"] = m.math->toJSON();
938	        mathList.push_back(jm);
939	    }
940	    j["math"] = mathList;
941	    j["math_enabled"] = mathEnabled();
942	
943	
944	    return j;
945	}
