947	void Trace::fromJSON(nlohmann::json j)
948	{
949	    source = Source::Live;
950	    if(j.contains("hash")) {
951	        hash = j["hash"];
952	        hashSet = true;
953	    } else {
954	        hashSet = false;
955	    }
956	    _name = QString::fromStdString(j.value("name", "Missing name"));
957	    _color = QColor(QString::fromStdString(j.value("color", "yellow")));
958	    visible = j.value("visible", true);
959	    auto type = QString::fromStdString(j.value("type", "Live"));
960	    if(j.contains("data")) {
961	        // Trace data is contained in the json, load now
962	        clear();
963	        {
964	            QMutexLocker locker(&dataMutex);
965	            for(auto jpoint : j["data"]) {
966	                Data d;
967	                d.x = jpoint.value("x", 0.0);
968	                d.y = complex<double>(jpoint.value("real", 0.0), jpoint.value("imag", 0.0));
969	                data.push_back(d);
970	            }
971	        }
972	    }
973	    if(j.contains("deembeddingData")) {
974	        // Deembedded data is contained in the json, load now
975	        clearDeembedding();
976	        {
977	            QMutexLocker locker(&dataMutex);
978	            for(auto jpoint : j["deembeddingData"]) {
979	                Data d;
980	                d.x = jpoint.value("x", 0.0);
981	                d.y = complex<double>(jpoint.value("real", 0.0), jpoint.value("imag", 0.0));
982	                deembeddingData.push_back(d);
983	            }
984	        }
985	    }
986	    deembeddingActive = j.value("deembeddingActive", false);
987	
988	    if(type == "Live") {
989	        if(j.contains("parameter")) {
990	            if(j["parameter"].type() == nlohmann::json::value_t::string) {
991	                liveParam = QString::fromStdString(j.value("parameter", "S11"));
992	            } else {
993	                // old parameter setting is stored as a number
994	                auto index = j.value("parameter", 0);
995	                const QString parameterList[] = {"S11", "S12", "S21", "S22", "PORT1", "PORT2"};
996	                if(index < 6) {
997	                    liveParam = parameterList[index];
998	                } else {
999	                    liveParam = "S11";
1000	                }
1001	            }
1002	        }
1003	
1004	        _liveType = j.value("livetype", LivedataType::Overwrite);
1005	        paused = j.value("paused", false);
1006	    } else if(type == "Touchstone" || type == "File") {
1007	        source = Source::File;
1008	        auto filename = QString::fromStdString(j.value("filename", ""));
1009	        fileParameter = j.value("parameter", 0);
1010	        try {
1011	            if(filename.endsWith(".csv")) {
1012	                auto csv = CSV::fromFile(filename);
1013	                fillFromCSV(csv, fileParameter);
1014	            } else {
1015	                // has to be a touchstone file
1016	                Touchstone t = Touchstone::fromFile(filename.toStdString());
1017	                fillFromTouchstone(t, fileParameter);
1018	            }
1019	        } catch (const exception &e) {
1020	            qWarning() << "Failed to create from file:" << QString::fromStdString(e.what());
1021	        }
1022	    } else if(type == "Math") {
1023	        source = Source::Math;
1024	        mathFormula = QString::fromStdString(j.value("expression", ""));
1025	        if(j.contains("sources")) {
1026	            for(auto js : j["sources"]) {
1027	                auto hash = js.value("trace", 0);
1028	                QString varName = QString::fromStdString(js.value("variable", ""));
1029	                if(!addMathSource(hash, varName)) {
1030	                    qWarning() << "Unable to find requested math source trace ( hash:"<<hash<<"), probably not loaded yet";
1031	                    mathSourceUnresolvedHashes[hash] = varName;
1032	                }
1033	            }
1034	        }
1035	        fromMath();
1036	    } else if(type == "Calibration") {
1037	        source = Source::Calibration;
1038	        // data has already been loaded if present in the file
1039	    }
1040	    vFactor = j.value("velocityFactor", 0.66);
1041	    reference_impedance = j.value("referenceImpedance", 50.0);
1042	    reflection = j.value("reflection", false);
1043	    for(auto jm : j["math"]) {
1044	        QString operation = QString::fromStdString(jm.value("operation", ""));
1045	        if(operation.isEmpty()) {
1046	            qWarning() << "Skipping empty math operation";
1047	            continue;
1048	        }
1049	        // attempt to find the type of operation
1050	        TraceMath::Type type = Type::Last;
1051	        for(unsigned int i=0;i<(int) Type::Last;i++) {
1052	            auto info = TraceMath::getInfo((Type) i);
1053	            if(info.name == operation) {
1054	                // found the correct operation
1055	                type = (Type) i;
1056	                break;
1057	            }
1058	        }
1059	        if(type == Type::Last) {
1060	            // unable to find this operation
1061	            qWarning() << "Unable to create math operation:" << operation;
1062	            continue;
1063	        }
1064	        qDebug() << "Creating math operation of type:" << operation;
1065	        auto op = TraceMath::createMath(type)[0];
1066	        if(jm.contains("settings")) {
1067	            op->fromJSON(jm["settings"]);
1068	        }
1069	        MathInfo info;
1070	        info.enabled = jm.value("enabled", true);
1071	        info.math = op;
1072	        op->assignInput(lastMath);
1073	        mathOps.push_back(info);
1074	        updateLastMath(mathOps.rbegin());
1075	    }
1076	    enableMath(j.value("math_enabled", true));
1077	    // indicate successful loading of trace data
1078	    success();
1079	}
