1081	unsigned int Trace::toHash(bool forceUpdate)
1082	{
1083	    if(!hashSet || forceUpdate) {
1084	        // taking the easy way: create the json string and hash it (already contains all necessary information)
1085	        // This is slower than it could be, but this function is only used when loading setups, so this isn't a big problem
1086	        JSONskipHash = true;
1087	        std::string json_string = toJSON().dump();
1088	        JSONskipHash = false;
1089	        hash = std::hash<std::string>{}(json_string);
1090	        hashSet = true;
1091	    }
1092	    return hash;
1093	}
