1095	std::vector<Trace *> Trace::createFromTouchstone(Touchstone &t)
1096	{
1097	    qDebug() << "Creating traces from touchstone...";
1098	    std::vector<Trace*> traces;
1099	    for(unsigned int i=0;i<t.ports()*t.ports();i++) {
1100	        auto trace = new Trace();
1101	        trace->fillFromTouchstone(t, i);
1102	        unsigned int sink = i / t.ports() + 1;
1103	        unsigned int source = i % t.ports() + 1;
1104	        trace->setName("S"+QString::number(sink)+QString::number(source));
1105	        traces.push_back(trace);
1106	    }
1107	    return traces;
1108	}
