1110	std::vector<Trace *> Trace::createFromCSV(CSV &csv)
1111	{
1112	    qDebug() << "Creating traces from csv...";
1113	    std::vector<Trace*> traces;
1114	    auto n = csv.columns();
1115	    if(n >= 2) {
1116	        try {
1117	            // This will throw once no more column is available, can use infinite loop
1118	            unsigned int param = 0;
1119	            while(1) {
1120	                auto t = new Trace();
1121	                auto name = t->fillFromCSV(csv, param);
1122	                t->setName(name);
1123	                param++;
1124	                traces.push_back(t);
1125	            }
1126	        } catch (const exception &e) {
1127	            // nothing to do, this simply means we reached the end of the csv columns
1128	        }
1129	    } else {
1130	        qWarning() << "Unable to parse, not enough columns";
1131	    }
1132	    return traces;
1133	}
