1135	std::vector<DeviceDriver::VNAMeasurement> Trace::assembleDatapoints(std::map<QString, Trace *> traceSet)
1136	{
1137	    vector<DeviceDriver::VNAMeasurement> ret;
1138	
1139	    // Sanity check traces
1140	    unsigned int samples = 0;
1141	    auto impedance = 0;
1142	    vector<double> freqs;
1143	    for(auto m : traceSet) {
1144	        const Trace *t = m.second;
1145	        if(!t) {
1146	            // trace not valid, skip
1147	            continue;
1148	        }
1149	        if(samples == 0) {
1150	            samples = t->size();
1151	        } else if(t->size() != samples) {
1152	            qWarning() << "Selected traces do not have the same size";
1153	            return ret;
1154	        }
1155	        if(impedance == 0) {
1156	            impedance = t->getReferenceImpedance();
1157	        } else if(t->getReferenceImpedance() != impedance) {
1158	            qWarning() << "Selected traces do not have the same reference impedance";
1159	            return ret;
1160	        }
1161	        if(t->outputType() != Trace::DataType::Frequency) {
1162	            qWarning() << "Selected trace not in frequency domain";
1163	            return ret;
1164	        }
1165	        if(freqs.empty()) {
1166	            // Create frequency vector
1167	            for(unsigned int i=0;i<samples;i++) {
1168	                freqs.push_back(t->sample(i).x);
1169	            }
1170	        } else {
1171	            // Compare with frequency vector
1172	            for(unsigned int i=0;i<samples;i++) {
1173	                if(t->sample(i).x != freqs[i]) {
1174	                    qWarning() << "Selected traces do not have identical frequency points";
1175	                    return ret;
1176	                }
1177	            }
1178	        }
1179	    }
1180	
1181	    if(samples == 0 || freqs.size() == 0) {
1182	        qWarning() << "Empty trace set";
1183	        return ret;
1184	    }
1185	
1186	    // Checks passed, assemble datapoints
1187	    for(unsigned int i=0;i<samples;i++) {
1188	        DeviceDriver::VNAMeasurement d;
1189	        for(auto m : traceSet) {
1190	            QString measurement = m.first;
1191	            const Trace *t = m.second;
1192	            if(t) {
1193	                d.measurements[measurement] = t->sample(i).y;
1194	            } else {
1195	                d.measurements[measurement] = 0.0;
1196	            }
1197	        }
1198	        d.pointNum = i;
1199	        d.frequency = freqs[i];
1200	        d.Z0 = impedance;
1201	        ret.push_back(d);
1202	    }
1203	    return ret;
1204	}
