1230	void Trace::updateLastMath(vector<MathInfo>::reverse_iterator start)
1231	{
1232	    TraceMath *newLast = nullptr;
1233	    for(auto it = start;it != mathOps.rend();it++) {
1234	        if(it->enabled) {
1235	            newLast = it->math;
1236	            break;
1237	        }
1238	    }
1239	    Q_ASSERT(newLast != nullptr);
1240	    if(newLast != lastMath) {
1241	        if(lastMath != nullptr) {
1242	            disconnect(lastMath, &TraceMath::outputSamplesChanged, this, nullptr);
1243	        }
1244	        lastMath = newLast;
1245	        // relay signals of end of math chain
1246	        connect(lastMath, &TraceMath::outputSamplesChanged, this, &Trace::dataChanged);
1247	        emit lastMathChanged();
1248	        emit typeChanged(this);
1249	        emit outputSamplesChanged(0, data.size());
1250	    }
1251	}
