1388	void Trace::swapMathOrder(unsigned int index)
1389	{
1390	    if(index < 1 || index + 1 >= mathOps.size()) {
1391	        return;
1392	    }
1393	    // store enable state and disable prior to swap (can reuse enable/disable function to handle input assignment)
1394	    bool index_enabled = mathOps[index].enabled;
1395	    bool next_enabled = mathOps[index].enabled;
1396	    enableMathOperation(index, false);
1397	    enableMathOperation(index + 1, false);
1398	    // actually swap the information
1399	    swap(mathOps[index], mathOps[index+1]);
1400	    // restore enable state
1401	    enableMathOperation(index, next_enabled);
1402	    enableMathOperation(index + 1, index_enabled);
