1405	void Trace::enableMathOperation(unsigned int index, bool enable)
1406	{
1407	    if(index < 1 || index >= mathOps.size()) {
1408	        return;
1409	    }
1410	    if(mathOps[index].enabled != enable) {
1411	        // find the next and previous operations that are enabled
1412	        unsigned int next_index = index + 1;
1413	        for(;next_index<mathOps.size();next_index++) {
1414	            if(mathOps[next_index].enabled) {
1415	                break;
1416	            }
1417	        }
1418	        unsigned int prev_index = index - 1;
1419	        for(;prev_index>0;prev_index--) {
1420	            if(mathOps[prev_index].enabled) {
1421	                break;
1422	            }
1423	        }
1424	        if(enable) {
1425	            // assign the previous enabled operation as the input for this operation
1426	            mathOps[index].math->assignInput(mathOps[prev_index].math);
1427	            // if another operation was active after index, reassign its input to index
1428	            if(next_index < mathOps.size()) {
1429	                mathOps[next_index].math->assignInput(mathOps[index].math);
1430	            }
1431	        } else {
1432	            // this operation gets disabled, reassign possible operation after it
1433	            if(next_index < mathOps.size()) {
1434	                mathOps[next_index].math->assignInput(mathOps[prev_index].math);
1435	            }
1436	            mathOps[index].math->removeInput();
1437	        }
1438	        mathOps[index].enabled = enable;
1439	        updateLastMath(mathOps.rbegin());
1440	    }
1441	}
