1510	double Trace::findExtremum(bool max, double xmin, double xmax)
1511	{
1512	    double compare = max ? numeric_limits<double>::min() : numeric_limits<double>::max();
1513	    double freq = 0.0;
1514	    for(auto sample : lastMath->getData()) {
1515	        if(sample.x < xmin || sample.x > xmax) {
1516	            continue;
1517	        }
1518	        double amplitude = abs(sample.y);
1519	        if((max && (amplitude > compare)) || (!max && (amplitude < compare))) {
1520	            // higher/lower extremum found
1521	            compare = amplitude;
1522	            freq = sample.x;
1523	        }
1524	    }
1525	    return freq;
1526	}
