1528	std::vector<double> Trace::findPeakFrequencies(unsigned int maxPeaks, double minLevel, double minValley, double xmin, double xmax, bool negativePeaks)
1529	{
1530	    if(outputType() != DataType::Frequency) {
1531	        // not in frequency domain
1532	        return vector<double>();
1533	    }
1534	    if(negativePeaks) {
1535	        minLevel = -minLevel;
1536	    }
1537	    using peakInfo = struct peakinfo {
1538	        double frequency;
1539	        double level_dbm;
1540	    };
1541	    vector<peakInfo> peaks;
1542	    double frequency = 0.0;
1543	    double max_dbm = -200.0;
1544	    double min_dbm = 200.0;
1545	    for(auto d : lastMath->getData()) {
1546	        if(d.x < xmin || d.x > xmax) {
1547	            continue;
1548	        }
1549	        double dbm = Util::SparamTodB(d.y);
1550	        if(negativePeaks) {
1551	            dbm = -dbm;
1552	        }
1553	        if((dbm >= max_dbm) && (min_dbm <= dbm - minValley)) {
1554	            // potential peak frequency
1555	            frequency = d.x;
1556	            max_dbm = dbm;
1557	        }
1558	        if(dbm <= min_dbm) {
1559	            min_dbm = dbm;
1560	        }
1561	        if((dbm <= max_dbm - minValley) && (max_dbm >= minLevel) && frequency) {
1562	            // peak was high enough and dropped below minValley afterwards
1563	            peakInfo peak;
1564	            peak.frequency = frequency;
1565	            peak.level_dbm = max_dbm;
1566	            peaks.push_back(peak);
1567	            // reset
1568	            frequency = 0.0;
1569	            max_dbm = -200.0;
1570	            min_dbm = dbm;
1571	        }
1572	    }
1573	    if(peaks.size() > maxPeaks) {
1574	        // found more peaks than requested, remove excess peaks
1575	        // sort with descending peak level
1576	        sort(peaks.begin(), peaks.end(), [](peakInfo higher, peakInfo lower) {
1577	           return higher.level_dbm >= lower.level_dbm;
1578	        });
1579	        // only keep the requested number of peaks
1580	        peaks.resize(maxPeaks);
1581	        // sort again with ascending frequencies
1582	        sort(peaks.begin(), peaks.end(), [](peakInfo lower, peakInfo higher) {
1583	           return higher.frequency >= lower.frequency;
1584	        });
1585	    }
1586	    vector<double> frequencies;
1587	    for(auto p : peaks) {
1588	        frequencies.push_back(p.frequency);
1589	    }
1590	    return frequencies;
1591	}
