1621	Trace::Data Trace::getInterpolatedSample(double x)
1622	{
1623	    if(deembeddingActive) {
1624	        QMutexLocker locker(&dataMutex);
1625	        Data ret;
1626	        if(deembeddingData.empty()) {
1627	            // Fall back to regular trace data below, after releasing dataMutex.
1628	        } else if(x < deembeddingData.front().x || x > deembeddingData.back().x) {
1629	            ret.y = std::numeric_limits<std::complex<double>>::quiet_NaN();
1630	            ret.x = std::numeric_limits<double>::quiet_NaN();
1631	        } else {
1632	            auto it = lower_bound(deembeddingData.begin(), deembeddingData.end(), x, [](const Data &lhs, const double x) -> bool {
1633	                return lhs.x < x;
1634	            });
1635	            if(it->x == x) {
1636	                ret = *it;
1637	            } else {
1638	                // no exact match, needs to interpolate
1639	                auto high = *it;
1640	                it--;
1641	                auto low = *it;
1642	                double alpha = (x - low.x) / (high.x - low.x);
1643	                ret.y = low.y * (1 - alpha) + high.y * alpha;
1644	                ret.x = x;
1645	            }
1646	        }
1647	        if(!deembeddingData.empty()) {
1648	            return ret;
1649	        }
1650	    } else {
1651	        return TraceMath::getInterpolatedSample(x);
1652	    }
