1728	double Trace::getGroupDelay(double frequency)
1729	{
1730	    if(!isVNAParameter(liveParam) || lastMath->getDataType() != DataType::Frequency) {
1731	        // data not suitable for group delay calculation
1732	        return std::numeric_limits<double>::quiet_NaN();
1733	    }
1734	
1735	    // get index that matches frequency best
1736	    unsigned int sample = index(frequency);
1737	
1738	    auto &p = Preferences::getInstance();
1739	    const unsigned int requiredSamples = p.Acquisition.groupDelaySamples;
1740	    if(size() < requiredSamples) {
1741	        // unable to calculate
1742	        return std::numeric_limits<double>::quiet_NaN();
1743	
1744	    }
1745	    // needs at least some samples before/after current sample for calculating the derivative.
1746	    // For samples too far at either end of the trace, return group delay of "inner" trace sample instead
1747	    if(sample < requiredSamples / 2) {
1748	        sample = requiredSamples / 2;
1749	    } else if(sample >= size() - requiredSamples / 2) {
1750	        sample = size() - requiredSamples / 2 - 1;
1751	    }
1752	
1753	    // got enough samples at either end to calculate derivative.
1754	    // acquire phases of the required samples
1755	    std::vector<double> phases;
1756	    phases.reserve(requiredSamples);
1757	    for(unsigned int index = sample - requiredSamples / 2;index <= sample + requiredSamples / 2;index++) {
1758	        phases.push_back(arg(this->sample(index).y));
1759	    }
1760	    // make sure there are no phase jumps
1761	    Util::unwrapPhase(phases);
1762	    // calculate linearRegression to get derivative
1763	    double B_0, B_1;
1764	    Util::linearRegression(phases, B_0, B_1);
1765	    // B_1 now contains the derived phase vs. the sample. Scale by frequency to get group delay
1766	    double freq_step = this->sample(sample).x - this->sample(sample - 1).x;
1767	    return -B_1 / (2.0*M_PI * freq_step);
1768	}
