9	static void createEvenlySpacedTicks(vector<double>& ticks, double start, double stop, unsigned int divisions) {
10	    ticks.clear();
11	    if(start > stop) {
12	        swap(start, stop);
13	    }
14	    auto step = (stop - start) / divisions;
15	    constexpr unsigned int maxTicks = 100;
16	    for(double tick = start; tick - stop < numeric_limits<double>::epsilon() && ticks.size() <= maxTicks;tick+= step) {
17	        ticks.push_back(tick);
18	    }
19	}
20	
21	static unsigned int createAutomaticTicks(vector<double>& ticks, double start, double stop, int minDivisions) {
22	    Q_ASSERT(stop > start);
23	    ticks.clear();
24	    double max_div_step = (stop - start) / minDivisions;
25	    int zeros = floor(log10(max_div_step));
26	    double decimals_shift = pow(10, zeros);
27	    max_div_step /= decimals_shift;
28	    if(max_div_step >= 5) {
29	        max_div_step = 5;
30	    } else if(max_div_step >= 2) {
31	        max_div_step = 2;
32	    } else {
33	        max_div_step = 1;
34	    }
35	    auto div_step = max_div_step * decimals_shift;
36	    // round min up to next multiple of div_step
37	    auto start_div = ceil(start / div_step) * div_step;
38	    for(double tick = start_div;tick <= stop;tick += div_step) {
39	        ticks.push_back(tick);
40	    }
41	    return (stop - start) / div_step;
42	}
43	
44	static void createLogarithmicTicks(vector<double>& ticks, double start, double stop, int minDivisions) {
45	    double mult = 1.0;
46	    if(start < 0.0 && stop < 0.0) {
47	        mult = -1.0;
48	        auto buf = -stop;
49	        stop = -start;
50	        start = buf;
51	    }
52	
53	    // enforce usable log settings
54	    if(start <= 0) {
55	        start = 1.0;
56	    }
57	    if(stop <= start) {
58	        stop = start + 1.0;
59	    }
60	    ticks.clear();
61	
62	    auto decades = log10(stop) - log10(start);
63	    double max_div_decade = minDivisions / decades;
64	    int zeros = floor(log10(max_div_decade));
65	    double decimals_shift = pow(10, zeros);
66	    max_div_decade /= decimals_shift;
67	    if(max_div_decade <= 1) {
68	        max_div_decade = 1;
69	    } else if(max_div_decade < 2) {
70	        max_div_decade = 2;
71	    } else if(max_div_decade < 5) {
72	        max_div_decade = 5;
73	    } else {
74	        max_div_decade = 10;
75	    }
76	    auto step = pow(10, floor(log10(start))+1) / (max_div_decade * decimals_shift);
77	    // round min up to next multiple of div_step
78	    auto div = ceil(start / step) * step;
79	    if(floor(log10(div)) != floor(log10(start))) {
80	        // first div is already at the next decade
81	        step *= 10;
82	    }
83	    do {
84	        ticks.push_back(div * mult);
85	        if(ticks.size() > 1 && div != step && floor(log10(div)+std::numeric_limits<double>::epsilon()) != floor(log10(div - step)+std::numeric_limits<double>::epsilon())) {
86	            // reached a new decade with this switch
87	            step *= 10;
88	        }
89	        div += step;
90	    } while(div <= stop);
91	
92	    if(mult == -1.0) {
93	        std::reverse(ticks.begin(), ticks.end());
94	    }
95	}
