103	double YAxis::sampleToCoordinate(Trace::Data data, Trace *t, unsigned int sample)
104	{
105	    switch(type) {
106	    case YAxis::Type::Magnitude:
107	        return Util::SparamTodB(data.y);
108	    case YAxis::Type::MagnitudedBuV:
109	        return Util::dBmTodBuV(Util::SparamTodB(data.y));
110	    case YAxis::Type::MagnitudeLinear:
111	        return abs(data.y);
112	    case YAxis::Type::Phase:
113	        return Util::SparamToDegree(data.y);
114	    case YAxis::Type::UnwrappedPhase:
115	        if(!t) {
116	            return 0.0;
117	        }
118	        return t->getUnwrappedPhase(sample) * 180.0 / M_PI;
119	    case YAxis::Type::VSWR:
120	        return Util::SparamToVSWR(data.y);
121	    case YAxis::Type::Real:
122	        return data.y.real();
123	    case YAxis::Type::Imaginary:
124	        return data.y.imag();
125	    case YAxis::Type::AbsImpedance:
126	        return abs(Util::SparamToImpedance(data.y, t->getReferenceImpedance()));
127	    case YAxis::Type::SeriesR:
128	        return Util::SparamToResistance(data.y, t->getReferenceImpedance());
129	    case YAxis::Type::Reactance:
130	        return Util::SparamToImpedance(data.y, t->getReferenceImpedance()).imag();
131	    case YAxis::Type::Capacitance:
132	        return Util::SparamToCapacitance(data.y, data.x, t->getReferenceImpedance());
133	    case YAxis::Type::Inductance:
134	        return Util::SparamToInductance(data.y, data.x);
135	    case YAxis::Type::QualityFactor:
136	        return Util::SparamToQualityFactor(data.y);
137	    case YAxis::Type::GroupDelay:
138	        if(!t) {
139	            return 0.0;
140	        }
141	        return t->getGroupDelay(data.x);
142	    case YAxis::Type::ImpulseReal:
143	        return real(data.y);
144	    case YAxis::Type::ImpulseMag:
145	        return Util::SparamTodB(data.y);
146	    case YAxis::Type::Step:
147	        if(!t) {
148	            return 0.0;
149	        }
150	        return t->sample(sample, true).y.real();
151	    case YAxis::Type::Impedance: {
152	        if(!t) {
153	            return 0.0;
154	        }
155	        double step = t->sample(sample, true).y.real();
156	        if(abs(step) < 1.0) {
157	            return Util::SparamToImpedance(step, t->getReferenceImpedance()).real();
158	        }
159	    }
160	        break;
161	    case YAxis::Type::Disabled:
162	    case YAxis::Type::Last:
163	        // no valid axis
164	        break;
165	    }
166	    return 0.0;
167	}
