366	std::complex<double> YAxis::reconstructValueFromYAxisType(std::map<YAxis::Type, double> yaxistypes)
367	{
368	    std::complex<double> ret = std::numeric_limits<std::complex<double>>::quiet_NaN();
369	    if(yaxistypes.count(Type::Real)) {
370	        ret.real(yaxistypes[Type::Real]);
371	        if(yaxistypes.count(Type::Imaginary)) {
372	            ret.imag(yaxistypes[Type::Imaginary]);
373	        } else {
374	            ret.imag(0.0);
375	        }
376	    } else if(yaxistypes.count(Type::Magnitude) || yaxistypes.count(Type::MagnitudedBuV) || yaxistypes.count(Type::MagnitudeLinear)) {
377	        double maglin, phase;
378	        if(yaxistypes.count(Type::MagnitudeLinear)) {
379	            maglin = yaxistypes[Type::MagnitudeLinear];
380	        } else if(yaxistypes.count(Type::Magnitude)) {
381	            maglin = Util::dBToMagnitude(yaxistypes[Type::Magnitude]);
382	        } else {
383	            auto dBm = Util::dBuVTodBm(yaxistypes[Type::MagnitudedBuV]);
384	            maglin = Util::dBToMagnitude(dBm);
385	        }
386	        if(yaxistypes.count(Type::Phase)) {
387	            phase = yaxistypes[Type::Phase];
388	        } else {
389	            phase = 0.0;
390	        }
391	        ret = polar<double>(maglin, phase / 180.0 * M_PI);
392	    }
393	    return ret;
394	}
